WITH prepared AS (SELECT jsonb_array_elements('[{"slug":"adult-literacy-rate","intro":"نسبة السكان بعمر 15 سنة فأكثر الذين يستطيعون القراءة والكتابة مع فهم نص بسيط بحسب تعريف الجهة الإحصائية. أحدث قيمة مسجلة لليمن هي 37.09 % من عمر 15 فأكثر عن سنة 1994، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"أساسي لفهم فرص التعلم المستمر واستخدام المعلومات والخدمات الرقمية ومشاركة البالغين في الحياة الاقتصادية.","historical_context":"تحتوي قاعدة بيانات 967 على قيمة واحدة لهذا المؤشر، تخص سنة 1994 (37.09 % من عمر 15 فأكثر). لا يمكن رسم اتجاه زمني أو حساب نمو من نقطة واحدة.","limitations":"لا يقيس مستويات الفهم المتقدم أو جودة التعليم، ولا يمكن استخدام قياس قديم جداً لوصف مهارات السكان الحالية. تنبيه زمني: آخر سنة مسجلة هي 1994؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: معهد اليونسكو للإحصاء عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"معهد اليونسكو للإحصاء عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SE.ADT.LITR.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"broad-money-share-gdp","intro":"نسبة عرض النقد الواسع، الذي يشمل أدوات نقدية وودائع معينة بحسب تعريف النظام النقدي، إلى الناتج المحلي في السنة. أحدث قيمة مسجلة لليمن هي 34.74 % من الناتج المحلي عن سنة 2013، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد على دراسة حجم السيولة النقدية بالنسبة للنشاط الاقتصادي وكيف يتطور التمويل. يرتبط تفسيره ببنية المصارف ومدى استخدام الودائع والنقد.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (47.11 % من الناتج المحلي)، و2001 (33.57 % من الناتج المحلي)، و2013 (34.74 % من الناتج المحلي). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"ليس مقدار النقد المتداول في الجيوب وحده ولا دليلاً مباشراً على التضخم. كما تتأثر النسبة بتغير الناتج وتعاريف المكونات النقدية. تنبيه زمني: آخر سنة مسجلة هي 2013؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/FM.LBL.BMNY.GD.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"consumer-price-inflation","intro":"معدل التغير السنوي في مؤشر أسعار سلة سلع وخدمات استهلاكية تمثل إنفاق الأسر وفق طريقة الجهة الناشرة. أحدث قيمة مسجلة لليمن هي 8.1 % سنويا عن سنة 2014، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يوضح اتجاه الارتفاع العام للأسعار، وهو ضروري لتحليل القوة الشرائية والميزانيات الأسرية. تراجع معدل التضخم الموجب يعني تباطؤ الزيادة لا انخفاض الأسعار.","historical_context":"من النقاط المسجلة في السلسلة: 1991 (36 % سنويا)، و2002 (12.24 % سنويا)، و2014 (8.1 % سنويا). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يساوي ارتفاع سعر كل سلعة أو التضخم في جميع المناطق، ولا يقيس أثر اختلاف الدخل. وآخر سنة في السلسلة لا تصلح لتوصيف سعر السوق الحالي. تنبيه زمني: آخر سنة مسجلة هي 2014؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"crude-birth-rate","intro":"عدد المواليد الأحياء في السنة مقابل كل ألف من إجمالي السكان، وليس عدد المواليد لكل امرأة. أحدث قيمة مسجلة لليمن هي 34.36 لكل 1000 شخص عن سنة 2024، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يوضح وتيرة المواليد في المجتمع ويفيد في تقدير متطلبات الخدمات الصحية والمدارس في السنوات القادمة.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (50.88 لكل 1000 شخص)، و2007 (37.53 لكل 1000 شخص)، و2024 (34.36 لكل 1000 شخص). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"يتأثر بتركيب السكان العمري؛ لذلك لا يساوي معدل الخصوبة الكلي، ولا يقيس احتمالات الإنجاب لفرد بعينه. تخص أحدث قيمة سنة 2024 ولا تصف بالضرورة ظروف 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SP.DYN.CBRT.IN?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"crude-death-rate","intro":"عدد الوفيات خلال السنة لكل ألف نسمة من السكان، وهو معدل خام غير معدل لاختلاف الأعمار. أحدث قيمة مسجلة لليمن هي 4.73 لكل 1000 شخص عن سنة 2024، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد في قراءة المؤشرات السكانية العامة وتخطيط أنظمة تسجيل الوفيات والخدمات الصحية. يفيد مقارنته بالمواليد والهيكل العمري.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (11.3 لكل 1000 شخص)، و2007 (6.08 لكل 1000 شخص)، و2024 (4.73 لكل 1000 شخص). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"الانخفاض لا يثبت تحسن الأمان الصحي وحده؛ فالمعدل الخام يتأثر بعمر السكان وأكتمال التسجيل وتقديرات الوفيات. ولا يساوي وفيات الأطفال أو ضحايا المعارك. تخص أحدث قيمة سنة 2024 ولا تصف بالضرورة ظروف 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SP.DYN.CDRT.IN?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"domestic-credit-private-sector","intro":"حجم الائتمان المحلي المقدم للقطاع الخاص نسبةً إلى الناتج المحلي، بحسب الجهات والأدوات الداخلة في السلسلة. أحدث قيمة مسجلة لليمن هي 5.64 % من الناتج المحلي عن سنة 2013، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يضيء جانباً من التمويل المتاح للأعمال والأفراد، ويساعد عند تقييم قدرة المشروعات على الحصول على الائتمان. يحتاج تفسيره إلى بيانات شروط القروض والمخاطر.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (5.22 % من الناتج المحلي)، و2001 (5.73 % من الناتج المحلي)، و2013 (5.64 % من الناتج المحلي). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يقيس سهولة اقتراض كل منشأة أو جودة القروض، ولا يبيّن تلقائياً توزيع التمويل على القطاعات والمحافظات. النسبة قد تتحرك بسبب تغير الناتج نفسه. تنبيه زمني: آخر سنة مسجلة هي 2013؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/FD.AST.PRVT.GD.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"external-debt-share-gni","intro":"نسبة رصيد الدين الخارجي إلى إجمالي الدخل القومي، وهي مقارنة بين التزامات متراكمة ودخل سنة واحدة. أحدث قيمة مسجلة لليمن هي 33.51 % من الدخل القومي عن سنة 2018، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"توفر مقياساً نسبياً لحجم الدين مقارنة بموارد الدخل الوطني. تكتمل الصورة مع آجال الاستحقاق والفوائد والصادرات.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (50.58 % من الدخل القومي)، و2004 (44.75 % من الدخل القومي)، و2018 (33.51 % من الدخل القومي). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا تقيس وحدها خطر التعثر أو مبلغ الأقساط المستحقة، وقد ترتفع بسبب انخفاض الدخل حتى إن لم يُستدن مبلغ جديد. بيانات السنوات القديمة لا تعكس المديونية الحالية. تنبيه زمني: آخر سنة مسجلة هي 2018؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/DT.DOD.DECT.GN.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"external-debt-stocks-total","intro":"إجمالي رصيد الالتزامات الخارجية القائمة عند نقطة القياس، لا حجم القروض الجديدة خلال السنة. أحدث قيمة مسجلة لليمن هي 7.09 مليار دولار عن سنة 2024، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد على متابعة مستوى التزامات الاقتصاد تجاه الدائنين الخارجيين، ويكمل ببيانات خدمة الدين والفوائد والعملة. لا تكفي قيمة الرصيد بمفردها لمعرفة القدرة على السداد.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (6.35 مليار دولار)، و2007 (6.16 مليار دولار)، و2024 (7.09 مليار دولار). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"ليس دين الحكومة المحلي كله، ولا يساوي خدمة الدين السنوية أو المدفوعات الفعلية. ويتأثر المقارنة بالدولار بتقلب العملات وتعريف الجهات الداخلة. تخص أحدث قيمة سنة 2024 ولا تصف بالضرورة ظروف 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/DT.DOD.DECT.CD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"female-population-share","intro":"حصة الإناث من مجموع السكان وفق التقديرات الديموغرافية؛ وهي نسبة سكانية لا مقياساً للمشاركة أو المساواة. أحدث قيمة مسجلة لليمن هي 49.33 % من السكان عن سنة 2025، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"مهمة لوضع المؤشرات الصحية والتعليمية والخدمية في سياق عدد النساء والفتيات. تُستخدم لإعداد المقامات الصحيحة للمعدلات حسب الجنس.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (49.84 % من السكان)، و2007 (49.42 % من السكان)، و2025 (49.33 % من السكان). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا تقيس تمثيل النساء في العمل أو السياسة أو التعليم، ولا تشرح أسباب الفوارق بين الأعمار. والاحتياجات الاجتماعية لا تُستنتج من النسبة وحدها. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SP.POP.TOTL.FE.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"fertility-rate-total","intro":"متوسط عدد المواليد الأحياء المتوقع أن تنجبهم امرأة افتراضية خلال حياتها إذا تعرضت لمعدلات الخصوبة العمرية لسنة القياس. أحدث قيمة مسجلة لليمن هي 4.5 مولود لكل امرأة عن سنة 2024، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد في فهم الاتجاه طويل الأجل لحجم الأسرة والنمو السكاني المتوقع واحتياجات الأمومة والطفولة.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (8.61 مولود لكل امرأة)، و2007 (5.26 مولود لكل امرأة)، و2024 (4.5 مولود لكل امرأة). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"ليس عدد أطفال كل امرأة بالفعل، ولا توقعاً مؤكداً لعدد مواليد الجيل الحالي؛ إذ تتغير المعدلات والسلوكيات مع الزمن. تخص أحدث قيمة سنة 2024 ولا تصف بالضرورة ظروف 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SP.DYN.TFRT.IN?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"firms-with-female-ownership","intro":"نسبة المنشآت المشمولة بمسح المنشآت التي توجد امرأة واحدة على الأقل ضمن مالكيها، وفق تعريف المسح. أحدث قيمة مسجلة لليمن هي 6.57 % من المنشآت عن سنة 2013، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يفيد في وصف جانب من مشاركة النساء في ملكية الأعمال الرسمية المشمولة، ويمكن ربطه بفرص التمويل والتسجيل والتدريب.","historical_context":"في سنة 2010 بلغت القيمة 6.42 % من المنشآت، وفي سنة 2013 بلغت 6.57 % من المنشآت. الفارق بين نقطتين لا يكشف مسار السنوات الواقعة بينهما، كما لا يثبت سبب التغير.","limitations":"لا يعني أن المرأة تملك الحصة المسيطرة أو تدير المنشأة، ولا يشمل تلقائياً المشروعات غير الرسمية أو المنزلية. عينة المسح وسنته تحددان إمكانية التعميم. تنبيه زمني: آخر سنة مسجلة هي 2013؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: مسوح المنشآت للبنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"مسوح المنشآت للبنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/IC.FRM.FEMO.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"gdp-annual-growth","intro":"نسبة تغير حجم الناتج المحلي الحقيقي من سنة إلى التي تسبقها، بعد استبعاد أثر تغير الأسعار بقدر ما تسمح منهجية الحسابات القومية. أحدث قيمة مسجلة لليمن هي 0.75 % سنويا عن سنة 2018، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يبيّن اتجاه توسع الإنتاج أو انكماشه ويكمل قراءة البطالة والاستثمار. تحسن المعدل بعد سنوات الانكماش لا يعني بالضرورة عودة الناتج إلى مستواه السابق.","historical_context":"من النقاط المسجلة في السلسلة: 1991 (6.29 % سنويا)، و2004 (3.97 % سنويا)، و2018 (0.75 % سنويا). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"معدل سنة واحدة لا يقيس الثروة المتراكمة ولا مستوى معيشة الأسر. وقد تتأثر تقديرات سنوات النزاع بفجوات البيانات ومراجعات الحسابات القومية. تنبيه زمني: آخر سنة مسجلة هي 2018؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - الحسابات القومية. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - الحسابات القومية — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/NY.GDP.MKTP.KD.ZG?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"gdp-current-usd","intro":"القيمة النقدية لإجمالي السلع والخدمات النهائية المنتجة داخل الاقتصاد خلال السنة، محسوبة بالأسعار الجارية بالدولار. أحدث قيمة مسجلة لليمن هي 21.61 مليار دولار عن سنة 2018، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يفيد في تقدير الحجم الاسمي للاقتصاد اليمني ومقارنته بموارد التجارة والتمويل. لقياس التعافي الاقتصادي يجب النظر أيضاً إلى النمو الحقيقي والقوة الشرائية.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (12.64 مليار دولار)، و2004 (13.87 مليار دولار)، و2018 (21.61 مليار دولار). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"التغير بالدولار الجاري يتأثر بالأسعار وسعر الصرف، ولا يعادل تغير حجم الإنتاج الحقيقي. ولا يخبرنا الإجمالي كيف يتوزع الدخل بين السكان. تنبيه زمني: آخر سنة مسجلة هي 2018؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - الحسابات القومية. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - الحسابات القومية — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/NY.GDP.MKTP.CD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"gdp-per-capita-current-usd","intro":"ناتج قسمة الناتج المحلي الإجمالي الجاري بالدولار على تقدير عدد السكان في السنة نفسها؛ وهو متوسط حسابي للإنتاج لا راتب للفرد. أحدث قيمة مسجلة لليمن هي 633.89 دولار أمريكي للفرد عن سنة 2018، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يتيح مقارنة الحجم الاسمي للنشاط الاقتصادي بعد مراعاة السكان، ويستكمل بمتوسط النمو ومستوى الأسعار. يمكن أن ينخفض المتوسط رغم زيادة بعض الأنشطة إذا تغير المقام أو الأسعار.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (910.42 دولار أمريكي للفرد)، و2004 (627.63 دولار أمريكي للفرد)، و2018 (633.89 دولار أمريكي للفرد). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"ليس متوسط دخل العامل أو الأجر، ولا يقيس الفقر أو توزيع الثروة. ويتأثر بسعر الصرف وبالتغير في تقدير السكان. تنبيه زمني: آخر سنة مسجلة هي 2018؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - الحسابات القومية. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - الحسابات القومية — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/NY.GDP.PCAP.CD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"government-education-expenditure","intro":"ما تخصصه الحكومة للتعليم مقارنة بحجم الناتج المحلي الإجمالي في السنة نفسها، وفق نطاق الإنفاق المحدد في المصدر. أحدث قيمة مسجلة لليمن هي 5.15 % من الناتج المحلي عن سنة 2008، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يكشف الوزن النسبي للإنفاق التعليمي في الاقتصاد، ويفيد عند مناقشة تمويل المدارس والمعلمين والتجهيزات. لفهم الفائدة يجب ضمه إلى بيانات التوزيع وكفاءة الإنفاق.","historical_context":"من النقاط المسجلة في السلسلة: 2000 (9.66 % من الناتج المحلي)، و2001 (9.24 % من الناتج المحلي)، و2008 (5.15 % من الناتج المحلي). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"ارتفاع الحصة لا يثبت جودة التعليم أو وصوله لكل طفل، وقد يرتفع بسبب انخفاض الناتج نفسه. والبيانات المتاحة قديمة ومحدودة السنوات. تنبيه زمني: آخر سنة مسجلة هي 2008؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: معهد اليونسكو للإحصاء عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"معهد اليونسكو للإحصاء عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SE.XPD.TOTL.GD.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"gross-fixed-capital-formation","intro":"قيمة الاستثمارات في الأصول الثابتة المستخدمة للإنتاج على مدى أكثر من سنة، كنسبة من الناتج المحلي؛ مثل البنية الأساسية والآلات والمباني. أحدث قيمة مسجلة لليمن هي 6.18 % من الناتج المحلي عن سنة 2018، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يعطي تصوراً عن تخصيص موارد الاقتصاد لزيادة القدرة الإنتاجية مستقبلاً. يمكن ربطه بالإنشاءات وتحديث المنشآت والبنية التحتية.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (10.5 % من الناتج المحلي)، و2004 (20.28 % من الناتج المحلي)، و2018 (6.18 % من الناتج المحلي). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يساوي عدد الشركات الجديدة أو صافي الاستثمار بعد الاهتلاك، ولا يقيس وحده جودة المشروعات أو مردودها. وتتأثر النسبة بمقدار الناتج في المقام. تنبيه زمني: آخر سنة مسجلة هي 2018؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - الحسابات القومية. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - الحسابات القومية — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/NE.GDI.FTOT.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"national-poverty-headcount","intro":"حصة السكان الذين يقع إنفاقهم أو مواردهم دون خط الفقر الوطني المعتمد في قياس المسح، وليس خط الفقر الدولي الموحّد. أحدث قيمة مسجلة لليمن هي 48.6 % من السكان عن سنة 2014، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يوضح حجم الحرمان الاقتصادي في سنة المسح، ويكتسب معنى أكبر إلى جانب أسعار الغذاء والدخل والخدمات. يجب الرجوع إلى تعريف خط الفقر وطريقة إجراء المسح.","historical_context":"تحتوي قاعدة بيانات 967 على قيمة واحدة لهذا المؤشر، تخص سنة 2014 (48.6 % من السكان). لا يمكن رسم اتجاه زمني أو حساب نمو من نقطة واحدة.","limitations":"تعكس القيمة قياساً تاريخياً ولا تصف فقر اليمن الحالي بعد تغير الظروف. ولا تجوز مقارنة النسبة آلياً بمقياس فقر يعتمد خطاً أو سنة مختلفة. تنبيه زمني: آخر سنة مسجلة هي 2014؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SI.POV.NAHC?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"net-migration","intro":"الفارق التقديري بين عدد الداخلين إلى البلاد والخارجين منها عبر فترة مرجعية محددة، وقد يظهر برقم سالب عند رجحان الخروج. أحدث قيمة مسجلة لليمن هي -16,291 شخص عن سنة 2025، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد على فهم أحد مكونات تغير السكان إضافة إلى المواليد والوفيات. وتفيد قراءته في تخطيط الخدمات والعلاقة بالمغتربين.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (-15,847 شخص)، و2007 (21,210 شخص)، و2025 (-16,291 شخص). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يمثل بالضرورة عدد اللاجئين أو النازحين داخل اليمن، ولا يرصد كل حركة فردية عبر الحدود. وتقديرات التدفقات تعتمد على نماذج ومصادر قد تُراجع. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SM.POP.NETM?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"official-exchange-rate","intro":"عدد وحدات الريال المقابلة لدولار أمريكي واحد وفق المتوسط الرسمي المسجل، وليس بالضرورة سعر التداول النقدي في الأسواق. أحدث قيمة مسجلة لليمن هي 1,355 ريال لكل دولار أمريكي عن سنة 2023، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يفيد في فهم الحسابات الرسمية والمعاملات المحوّلة إلى عملة وطنية. تزايد عدد الريالات مقابل الدولار يدل حسابياً على ضعف قيمة الريال بهذا المعيار.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (12.01 ريال لكل دولار أمريكي)، و2006 (197.05 ريال لكل دولار أمريكي)، و2023 (1,355 ريال لكل دولار أمريكي). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"في اقتصاد تتعدد فيه أسعار الصرف، لا يمثل المتوسط الرسمي بالضرورة أسعار صنعاء أو عدن أو السوق الموازية. لا يجوز استخدامه لتحديد تكلفة شراء الدولار اليوم. تخص أحدث قيمة سنة 2023 ولا تصف بالضرورة ظروف 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"personal-remittances-received","intro":"تدفقات التحويلات الشخصية الواردة إلى اليمن كما تُحصيها إحصاءات ميزان المدفوعات والمصادر المعتمدة بالدولار الجاري. أحدث قيمة مسجلة لليمن هي 3.77 مليار دولار عن سنة 2016، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"توضح إحدى قنوات دعم دخل الأسر والتدفقات عبر الحدود، وتساعد في دراسة الصلات الاقتصادية للمغتربين. لقراءة أثرها ينبغي النظر إلى الأسعار والرسوم وقنوات التحويل.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (1.50 مليار دولار)، و2003 (1.27 مليار دولار)، و2016 (3.77 مليار دولار). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا تمثل جميع الأموال المحمولة نقداً أو التحويلات خارج القنوات المرصودة، ولا تعني أن كل أسرة تستقبل مبالغ. اختلاف أسعار الصرف والأسعار يغيّر القيمة الحقيقية المستفادة. تنبيه زمني: آخر سنة مسجلة هي 2016؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/BX.TRF.PWKR.CD.DT?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"population-age-0-14","intro":"حصة الأطفال من عمر صفر حتى 14 سنة ضمن إجمالي السكان، محسوبة وفق تقديرات العمر والسكان. أحدث قيمة مسجلة لليمن هي 41.02 % من السكان عن سنة 2025، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"تفيد في تقدير الاحتياجات المستقبلية للتعليم الأساسي والتطعيم والخدمات الموجهة للأسر. وتكشف جزءاً من البنية العمرية للسكان.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (51.06 % من السكان)، و2007 (45.27 % من السكان)، و2025 (41.02 % من السكان). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"النسبة ليست عدد الأطفال الفعلي، ولا تقيس وحدها نسبة الالتحاق بالمدارس. وانخفاضها النسبي لا يعني بالضرورة انخفاض عدد الأطفال عددياً. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SP.POP.0014.TO.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"population-age-15-64","intro":"حصة السكان من عمر 15 إلى 64 سنة ضمن السكان، وهي فئة عمرية اصطلاحية تختلف عن تعريف قوة العمل المستخدمة لقياس البطالة. أحدث قيمة مسجلة لليمن هي 56.43 % من السكان عن سنة 2025، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"تساعد في تقدير حجم الفئة التي تضم كثيراً من الأعمار النشطة اقتصادياً، والتخطيط للتعليم والتشغيل والتأهيل المهني.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (46.1 % من السكان)، و2007 (51.97 % من السكان)، و2025 (56.43 % من السكان). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"ليس كل فرد في هذه الفئة موظفاً أو راغباً في العمل، كما لا يُستبعد أن يعمل أفراد أصغر أو أكبر. ولا يساوي المؤشر نسبة العاملين. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SP.POP.1564.TO.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"population-age-65-plus","intro":"حصة سكان اليمن الذين تبلغ أعمارهم 65 سنة أو أكثر من إجمالي السكان في سنة القياس. أحدث قيمة مسجلة لليمن هي 2.55 % من السكان عن سنة 2025، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"تُستخدم في التخطيط للرعاية الصحية والخدمات الاجتماعية وحاجات كبار السن. المقارنة الزمنية تشير إلى تغير الوزن النسبي لهذه الفئة بين الأعمار.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (2.84 % من السكان)، و2007 (2.76 % من السكان)، و2025 (2.55 % من السكان). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا تخبر النسبة عن صحة كبار السن أو حصولهم على معاشات ورعاية، ولا عن عددهم المطلق دون إجمالي سكاني متوافق. وقد تتغير النسبة بسبب تغير الفئات العمرية الأخرى. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SP.POP.65UP.TO.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"primary-completion-rate","intro":"نسبة إكمال المرحلة الابتدائية ضمن الفئة العمرية المرجعية حسب تعريف اليونسكو والبنك الدولي، لا نسبة النجاح في اختبار واحد. أحدث قيمة مسجلة لليمن هي 60.14 % من الفئة العمرية عن سنة 2016، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"تعطي مؤشراً على قدرة النظام على إيصال المتعلمين إلى نهاية المرحلة الأساسية، وتكتمل بالصورة عن التسجيل والتسرب والجودة.","historical_context":"من النقاط المسجلة في السلسلة: 1999 (48.03 % من الفئة العمرية)، و2005 (53.49 % من الفئة العمرية)، و2016 (60.14 % من الفئة العمرية). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا تثبت اكتساب مهارات القراءة والرياضيات، ولا تعكس بالضرورة وضع المدارس في سنة اليوم. اختلاف طريقة الحساب والفئة المرجعية قد يؤثر على النسبة. تنبيه زمني: آخر سنة مسجلة هي 2016؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: معهد اليونسكو للإحصاء عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"معهد اليونسكو للإحصاء عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SE.PRM.CMPT.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"primary-school-enrollment-gross","intro":"إجمالي المقيدين بالتعليم الابتدائي بغض النظر عن أعمارهم كنسبة إلى السكان في العمر الرسمي لهذه المرحلة. أحدث قيمة مسجلة لليمن هي 76.98 % عن سنة 2016، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد على متابعة حجم التسجيل مقارنة بعدد الأطفال المتوقع في سن الابتدائي، ويكشف تأثير الالتحاق المتأخر أو الإعادة.","historical_context":"من النقاط المسجلة في السلسلة: 1999 (63.52 %)، و2005 (79.42 %)، و2016 (76.98 %). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"قد تتجاوز النسبة 100% لأن البسط يشمل أعماراً خارج العمر الرسمي. ولا تعني وحدها الحضور اليومي أو إكمال الدراسة أو تعلم المهارات. تنبيه زمني: آخر سنة مسجلة هي 2016؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: معهد اليونسكو للإحصاء عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"معهد اليونسكو للإحصاء عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SE.PRM.ENRR?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"scientific-technical-journal-articles","intro":"عدد المقالات العلمية والتقنية اليمنية المصنفة ضمن قواعد النشر والمجلات الداخلة في المنهجية، وليس كل إنتاج معرفي منشور محلياً. أحدث قيمة مسجلة لليمن هي 404.01 مقالة عن سنة 2023، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد على رصد حضور الباحثين والمؤسسات في دوريات علمية محددة ومناقشة دعم البحث والتعاون الأكاديمي.","historical_context":"من النقاط المسجلة في السلسلة: 1996 (19.72 مقالة)، و2009 (78.96 مقالة)، و2023 (404.01 مقالة). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يساوي عدد الباحثين ولا مستوى جودة كل مقال، وقد يتأثر بطرق الفهرسة وإسناد الانتماء المؤسسي ومعايير النشر. تخص أحدث قيمة سنة 2023 ولا تصف بالضرورة ظروف 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: المنظمة العالمية للملكية الفكرية عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"المنظمة العالمية للملكية الفكرية عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/IP.JRN.ARTC.SC?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"secondary-school-enrollment-gross","intro":"عدد الملتحقين بالتعليم الثانوي من جميع الأعمار مقارنة بالسكان في العمر الرسمي للمرحلة. أحدث قيمة مسجلة لليمن هي 43.69 % عن سنة 2016، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يوضح اتساع الالتحاق بالمرحلة الثانوية وما يرتبط به من طلب على المدارس والمعلمين. تساعد مقارنته بالابتدائي على طرح أسئلة عن الانتقال بين المرحلتين.","historical_context":"من النقاط المسجلة في السلسلة: 1999 (36.08 %)، و2008 (37.98 %)، و2016 (43.69 %). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"هو معدل التحاق إجمالي قد يتجاوز 100%، وليس نسبة الإكمال أو النجاح أو الحضور المنتظم. لا يكشف اختلاف الالتحاق بين البنات والبنين دون بيانات منفصلة. تنبيه زمني: آخر سنة مسجلة هي 2016؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: معهد اليونسكو للإحصاء عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"معهد اليونسكو للإحصاء عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SE.SEC.ENRR?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"secure-internet-servers","intro":"عدد الخوادم الآمنة المسجلة أو المرصودة لكل مليون شخص وفق تعريف مؤشر الاتصالات، وهو مقياس تقني لا عدد مواقع اليمن كاملة. أحدث قيمة مسجلة لليمن هي 15.01 لكل مليون شخص عن سنة 2024، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يوضح جانباً من بنية الخدمات الرقمية وإتاحتها عبر اتصالات محمية، ويكتسب معنى بجانب انتشار الإنترنت والخدمات الإلكترونية.","historical_context":"من النقاط المسجلة في السلسلة: 2010 (0.19 لكل مليون شخص)، و2017 (2.84 لكل مليون شخص)، و2024 (15.01 لكل مليون شخص). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يثبت جودة أمن كل موقع أو خصوصية المستخدمين، ولا يقيس سرعة الإنترنت أو نسبة المتصلين. وقد تستضيف خدمات يمنية خوادم خارج البلاد. تخص أحدث قيمة سنة 2024 ولا تصف بالضرورة ظروف 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/IT.NET.SECR.P6?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"tertiary-enrollment-gross","intro":"عدد الملتحقين بالتعليم العالي من جميع الأعمار مقارنة بعدد السكان في الفئة العمرية المرجعية للتعليم العالي. أحدث قيمة مسجلة لليمن هي 8.81 % عن سنة 2011، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد على فهم حجم الوصول للتعليم الجامعي وما بعد الثانوي وعلى تقدير الحاجة إلى الطاقة الاستيعابية والتخصصات.","historical_context":"من النقاط المسجلة في السلسلة: 1992 (3.99 %)، و2005 (8.34 %)، و2011 (8.81 %). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يقيس جودة الجامعات أو التخرج أو ملاءمة التخصصات للعمل، وقد يختلف نطاق المؤسسات المحتسبة بين الجهات وسنوات القياس. تنبيه زمني: آخر سنة مسجلة هي 2011؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: معهد اليونسكو للإحصاء عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"معهد اليونسكو للإحصاء عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SE.TER.ENRR?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"trade-share-gdp","intro":"مجموع قيم الصادرات والواردات من السلع والخدمات كنسبة من الناتج المحلي الإجمالي، لا صافي الفرق بينهما. أحدث قيمة مسجلة لليمن هي 56.08 % من الناتج المحلي عن سنة 2018، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يستخدم لقياس انكشاف الاقتصاد على المبادلات الخارجية وحساسيته للاستيراد والتصدير. تساعد قراءته في فهم دور الموانئ واحتياجات الاستيراد.","historical_context":"من النقاط المسجلة في السلسلة: 1990 (27.63 % من الناتج المحلي)، و2004 (71.85 % من الناتج المحلي)، و2018 (56.08 % من الناتج المحلي). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"ارتفاع النسبة لا يعني فائضاً تجارياً أو قدرة تصديرية قوية، فقد تكون الواردات هي الغالبة. كما يؤثر تقلص الناتج على النسبة حتى دون زيادة المبادلات. تنبيه زمني: آخر سنة مسجلة هي 2018؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: البنك الدولي - الحسابات القومية. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"البنك الدولي - الحسابات القومية — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/NE.TRD.GNFS.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"unemployment-rate-total","intro":"نسبة من لا يعملون ويبحثون عن عمل ومتاحون له من إجمالي قوة العمل، وفق مفهوم منظمة العمل الدولية؛ وليس نسبة غير العاملين من السكان. أحدث قيمة مسجلة لليمن هي 17.32 % من قوة العمل عن سنة 2025، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد في رصد صعوبة الحصول على عمل، ويُقرأ إلى جانب مشاركة الشباب والنساء والعمل غير الرسمي. يمكن أن تتغير البطالة مع تغير عدد الداخلين إلى قوة العمل.","historical_context":"من النقاط المسجلة في السلسلة: 1991 (8.43 % من قوة العمل)، و2008 (12.66 % من قوة العمل)، و2025 (17.32 % من قوة العمل). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا تشمل النسبة كل شخص لا يبحث عن عمل، ولا تقيس نقص الأجور أو ساعات العمل غير الكافية. وتقديرات النموذج الإحصائي ليست حصراً ميدانياً لجميع الباحثين عن العمل. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: منظمة العمل الدولية عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"منظمة العمل الدولية عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SL.UEM.TOTL.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"vocational-secondary-enrollment-share","intro":"حصة الطلاب المسجلين في المسارات المهنية من إجمالي طلاب التعليم الثانوي وفق تعريف البرامج المدرجة. أحدث قيمة مسجلة لليمن هي 0.25 % من طلاب الثانوية عن سنة 2016، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يوضح موقع التدريب العملي ضمن خيارات التعليم الثانوي، وهو مدخل لمناقشة التأهيل للمهن والاحتياجات الإنتاجية.","historical_context":"من النقاط المسجلة في السلسلة: 1999 (0.9 % من طلاب الثانوية)، و2010 (0.69 % من طلاب الثانوية)، و2016 (0.25 % من طلاب الثانوية). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا يقيس جودة التدريب أو نسبة توظيف الخريجين، ولا يشمل تلقائياً جميع برامج التدريب خارج التعليم الثانوي النظامي. تنبيه زمني: آخر سنة مسجلة هي 2016؛ لا يجوز وصف قيمتها بأنها الوضع الحالي في 2026. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: معهد اليونسكو للإحصاء عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"معهد اليونسكو للإحصاء عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SE.SEC.ENRL.VO.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"yemen-population","intro":"تقدير إجمالي عدد المقيمين في اليمن ضمن التعريف والتوقيت المعتمدين لدى المصدر؛ ليس تعداداً سكانياً جديداً. أحدث قيمة مسجلة لليمن هي 42,961,653 نسمة عن سنة 2026، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"يساعد على تقدير حجم الاحتياج إلى المدارس والمستشفيات والمياه وعلى حساب نصيب الفرد. ويجب اختيار مرجع سكاني واحد عند مقارنة نسب الخدمات.","historical_context":"تحتوي قاعدة بيانات 967 على قيمة واحدة لهذا المؤشر، تخص سنة 2026 (42,961,653 نسمة). لا يمكن رسم اتجاه زمني أو حساب نمو من نقطة واحدة.","limitations":"هذا رقم تقديري لسنة محددة ولا يقدم توزيعاً دقيقاً للمحافظات أو المقيمين بالخارج أو النزوح الداخلي. ولا ينبغي خلط العداد اللحظي بتقدير منتصف السنة. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: عدد سكان اليمن. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"عدد سكان اليمن — السلسلة الأصلية","url":"https://worldpopulationreview.com/countries/yemen"}],"reviewed_on":"2026-10-27"},{"slug":"youth-unemployment-rate","intro":"نسبة العاطلين الباحثين عن عمل والمتاحين له من قوة العمل لدى الأعمار 15–24، وليس من جميع الشباب في تلك الفئة. أحدث قيمة مسجلة لليمن هي 32.6 % من قوة العمل بعمر 15 إلى 24 عن سنة 2025، وفق السلسلة المرتبطة بالمصدر المعلن.","why_it_matters":"تلفت الانتباه إلى صعوبات الانتقال من الدراسة إلى العمل ودخول سوق الوظائف لأول مرة. تُقرأ مع الالتحاق بالتعليم والتدريب ومشاركة الشباب في سوق العمل.","historical_context":"من النقاط المسجلة في السلسلة: 1991 (17.08 % من قوة العمل بعمر 15 إلى 24)، و2008 (21.37 % من قوة العمل بعمر 15 إلى 24)، و2025 (32.6 % من قوة العمل بعمر 15 إلى 24). هذه مقارنة بين سنوات فعلية من المصدر، ولا تثبت وحدها أسباب التغير أو استمراره في السنوات غير المتاحة.","limitations":"لا تشمل كل طالب أو شاب غير عامل؛ فمن لا يبحث عن وظيفة قد يكون خارج قوة العمل. ولا تقيس العمل غير الرسمي أو نقص ساعات العمل. لا ينبغي اعتبار المؤشر سبباً مباشراً لتغير مؤشر آخر دون دراسة مستقلة.","source_notes":"مصدر الأرقام المعتمد في 967: منظمة العمل الدولية عبر البنك الدولي. جاءت القيم من السلسلة الوطنية الموجودة في قسم «اليمن بالأرقام»؛ الروابط هنا تحيل إلى صفحة المؤشر المسجلة. مراجعة المحتوى بتاريخ 2026-10-27 لا تعني وجود قياس جديد أو تحقق ميداني، وقد يراجع الناشر تقديراته لاحقاً.","reference_links":[{"title":"منظمة العمل الدولية عبر البنك الدولي — السلسلة الأصلية","url":"https://data.worldbank.org/indicator/SL.UEM.1524.ZS?locations=YE"}],"reviewed_on":"2026-10-27"}]'::jsonb) AS d),
inserted AS (
 INSERT INTO public.stat_indicator_editorial(indicator_id,intro,why_it_matters,historical_context,limitations,source_notes,reference_links,reviewed_on,is_published)
 SELECT i.id,p.d->>'intro',p.d->>'why_it_matters',p.d->>'historical_context',p.d->>'limitations',p.d->>'source_notes',p.d->'reference_links',(p.d->>'reviewed_on')::date,true
 FROM prepared p JOIN public.stat_indicators i ON i.slug=p.d->>'slug'
 WHERE i.is_published AND i.slug <> 'access-to-electricity'
 ON CONFLICT(indicator_id) DO NOTHING
 RETURNING indicator_id
)
SELECT (SELECT count(*) FROM prepared) AS prepared,(SELECT count(*) FROM inserted) AS inserted;